export const DetachedWorkFoldSchema: GenMessage<DetachedWorkFold> = /*@__PURE__*/
  messageDesc(file_agentshim_frontend_v1_detached_work, 19);

/**
 * One incremental push to ONE MESSAGE'S detached-work payload: the message id
 * routes it, the arm types it.
 *
 * AN UPDATE, NOT A MESSAGE. It is addressed to a message that already exists
 * and mutates that message's payload in place. It carries no uuid, no lineage
 * and no timestamp of its own, because it is not a thing the feed contains —
 * it is a change to a thing the feed already contains. Promoting each one to a
 * Message would let an agent running for an hour insert a feed row per line,
 * which is exactly what pagination cannot survive.
 *
 * Never a re-send of the whole message either: an agent running for an hour
 * would otherwise re-transmit its entire transcript on every new line.
 *
 * @generated from message agentshim.frontend.v1.DetachedWorkUpdate
 */
export type DetachedWorkUpdate = Message<"agentshim.frontend.v1.DetachedWorkUpdate"> & {
  /**
   * WHICH MESSAGE this lands on — the uuid of a Message whose payload is
   * DetachedWork. Must name a message the receiver has already opened; an
   * update for an unknown id is a gap and must be rejected loudly and resynced,
   * never buffered in the hope its message shows up.
   *
   * @generated from field: string message_id = 1;
   */
  messageId: string;

  /**
   * WHAT changed. The arm MUST match the work's kind — a journal update
   * addressed to shell work is a daemon bug and is rejected, not coerced. Only
   * `liveness` is kind-independent.
   *
   * `shell` and `unclassified` are distinct arms carrying the SAME message:
   * the arm names which kind the update is for, while the payload is one byte
   * append at one offset in both cases. The two kinds differ in what they ARE,
   * not in how their output arrives, so there is no axis along which a
   * duplicated pair of append messages could evolve apart — only a
   * gap-detection rule that would have to be kept identical in two places.
   *
   * `merge` carries the SAME message as `agent` for exactly that reason: a
   * merge run's emissions arrive precisely as a detached agent's do, so the
   * arm names the kind while the payload has no axis to evolve apart on.
   *
   * @generated from oneof agentshim.frontend.v1.DetachedWorkUpdate.update
   */
  update: {
    /**
     * @generated from field: agentshim.frontend.v1.DetachedWorkAgentUpdate agent = 10;
     */
    value: DetachedWorkAgentUpdate;
    case: "agent";
  } | {
    /**
     * @generated from field: agentshim.frontend.v1.DetachedWorkJournalUpdate journal = 11;
     */
    value: DetachedWorkJournalUpdate;
    case: "journal";
  } | {
    /**
     * @generated from field: agentshim.frontend.v1.DetachedWorkOutputAppend shell = 12;
     */
    value: DetachedWorkOutputAppend;
    case: "shell";
  } | {
    /**
     * @generated from field: agentshim.frontend.v1.DetachedWorkOutputAppend unclassified = 13;
     */
    value: DetachedWorkOutputAppend;
    case: "unclassified";
  } | {
    /**
     * @generated from field: agentshim.frontend.v1.DetachedWorkLivenessUpdate liveness = 14;
     */
    value: DetachedWorkLivenessUpdate;
    case: "liveness";
  } | {
    /**
     * @generated from field: agentshim.frontend.v1.DetachedWorkAgentUpdate merge = 15;
     */
    value: DetachedWorkAgentUpdate;
    case: "merge";
  } | {
    /**
     * @generated from field: agentshim.frontend.v1.DetachedWorkSkillUpdate skill = 16;
     */
    value: DetachedWorkSkillUpdate;
    case: "skill";
  } | { case: undefined; value?: undefined };
};

