/**
 * New output from a detached agent.
 *
 * @generated from message agentshim.frontend.v1.DetachedWorkAgentUpdate
 */
export type DetachedWorkAgentUpdate = Message<"agentshim.frontend.v1.DetachedWorkAgentUpdate"> & {
  /**
   * The emissions produced since the last update, in order. THE SAME message
   * the top-level feed carries — see AgentEmission. A frontend appends these
   * to the work's emission list and renders them with its ordinary feed
   * renderers.
   *
   * These are EMISSIONS APPENDED TO ONE MESSAGE, not messages of their own: a
   * detached agent's thousand lines are a thousand additions to one feed row.
   *
   * @generated from field: repeated agentshim.frontend.v1.AgentEmission emissions = 1;
   */
  emissions: AgentEmission[];

  /**
   * The message's fold accounting AFTER applying this update. Restated rather
   * than deltaed: it is small, and a dropped-count that drifts is worse than
   * one that is re-sent.
   *
   * @generated from field: agentshim.frontend.v1.DetachedWorkFold fold = 2;
   */
  fold?: DetachedWorkFold | undefined;
};

